// Password-derived wrapping key; random data key. Keys live only in this tab.
const encoder=new TextEncoder(),decoder=new TextDecoder();
export const MAX_RECORDINGS=15;
export const MAX_SONGS=15;
export const MAX_PROFILE_BYTES=400*1024*1024;
const ITERATIONS=600000;
let session=null,queue=Promise.resolve();
export function activeProfile(){return session?{id:session.account.id,email:session.account.email}:null;}
export function lock(){session=null;}
export function b64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);}
export function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
async function derive(password,salt){const material=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:ITERATIONS,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function seal(key,bytes,aad){const iv=crypto.getRandomValues(new Uint8Array(12));const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:encoder.encode(aad)},key,bytes);return{iv,ciphertext};}
async function open(key,entry,aad){return crypto.subtle.decrypt({name:'AES-GCM',iv:entry.iv,additionalData:encoder.encode(aad)},key,entry.ciphertext);}
function database(){return new Promise((resolve,reject)=>{const r=indexedDB.open('mixlab-private-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('profiles',{keyPath:'id'}).createIndex('email','email',{unique:true});r.result.createObjectStore('items',{keyPath:'key'}).createIndex('owner','owner');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Cerrá otras pestañas de MixLab e intentá otra vez.'));});}
async function access(store,mode,fn){const d=await database();return new Promise((resolve,reject)=>{const tx=d.transaction(store,mode);let value;const request=fn(tx.objectStore(store));if(request)request.onsuccess=()=>value=request.result;tx.oncomplete=()=>{d.close();resolve(value);};tx.onerror=tx.onabort=()=>{d.close();reject(tx.error||Error('No se pudo guardar.'));};});}
const ownerRows=owner=>access('items','readonly',s=>s.index('owner').getAll(owner));
function serialize(fn){const result=queue.then(fn);queue=result.catch(()=>{});return result;}
async function commitItem(row){const d=await database();return new Promise((resolve,reject)=>{const tx=d.transaction('items','readwrite'),store=tx.objectStore('items'),r=store.index('owner').getAll(row.owner);let reason;r.onsuccess=()=>{const rows=r.result,old=rows.find(x=>x.key===row.key),replaced=rows.filter(x=>row.kind==='recording'&&x.kind==='draft'&&x.draftGroup===row.id);if(row.kind==='song'&&!old&&rows.filter(x=>x.kind==='song').length>=MAX_SONGS){reason=Error('Tu repertorio ya tiene 15 canciones. Quitá una para preparar otra.');tx.abort();return;}if(row.kind==='recording'&&!old&&rows.filter(x=>x.kind==='recording').length>=MAX_RECORDINGS){reason=Error('Ya tenés 15 grabaciones. Descargá y quitá una antes de grabar otra.');tx.abort();return;}if(rows.reduce((n,x)=>n+x.size,0)-(old?.size||0)-replaced.reduce((n,x)=>n+x.size,0)+row.size>MAX_PROFILE_BYTES){reason=Error('Tu perfil llegó a 400 MB. Hacé una copia y quitá archivos para liberar espacio.');tx.abort();return;}store.put(row);for(const x of replaced)store.delete(x.key);};tx.oncomplete=()=>{d.close();resolve();};tx.onerror=tx.onabort=()=>{d.close();reject(reason||tx.error||Error('No se pudo guardar.'));};});}
export async function createProfile(email,password){email=email.trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Escribí un correo válido.');if(password.length<10)throw Error('Usá una contraseña de al menos 10 caracteres.');if(await access('profiles','readonly',s=>s.index('email').get(email)))throw Error('Ya existe un perfil local con ese correo. Elegí Ingresar.');const id=crypto.randomUUID(),salt=crypto.getRandomValues(new Uint8Array(16)),raw=crypto.getRandomValues(new Uint8Array(32)),wrapping=await derive(password,salt),wrapped=await seal(wrapping,raw,id),account={id,email,salt,wrapped,iterations:ITERATIONS,version:1};await access('profiles','readwrite',s=>s.add(account));session={account,key:await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt'])};raw.fill(0);return activeProfile();}
export async function login(email,password){const account=await access('profiles','readonly',s=>s.index('email').get(email.trim().toLowerCase()));if(!account)throw Error('Correo o contraseña incorrectos en este dispositivo.');try{const wrapping=await derive(password,account.salt),raw=await open(wrapping,account.wrapped,account.id);session={account,key:await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt'])};new Uint8Array(raw).fill(0);return activeProfile();}catch{throw Error('Correo o contraseña incorrectos en este dispositivo.');}}
function requireSession(){if(!session)throw Error('Ingresá a tu perfil.');return session;}
export async function putItem(kind,id,meta,blob=null){const s=requireSession();return serialize(async()=>{const key=s.account.id+':'+id,bytes=blob?await blob.arrayBuffer():encoder.encode(JSON.stringify(meta)),data=await seal(s.key,bytes,key),info=await seal(s.key,encoder.encode(JSON.stringify({meta,type:blob?.type||'',blob:!!blob})),key+':meta');await commitItem({key,owner:s.account.id,id,kind,size:bytes.byteLength,data,info,draftGroup:kind==='draft'?meta.session:null});return id;});}
export async function getItems(kind){const s=requireSession(),rows=await ownerRows(s.account.id),out=[];for(const r of rows.filter(r=>r.kind===kind)){const info=JSON.parse(decoder.decode(await open(s.key,r.info,r.key+':meta')));out.push({...info.meta,id:r.id,size:r.size});}return out;}
export async function getItem(id){const s=requireSession(),r=await access('items','readonly',st=>st.get(s.account.id+':'+id));if(!r||r.owner!==s.account.id)return null;const info=JSON.parse(decoder.decode(await open(s.key,r.info,r.key+':meta'))),raw=await open(s.key,r.data,r.key);return{id,...info.meta,blob:info.blob?new Blob([raw],{type:info.type}):null,value:info.blob?null:JSON.parse(decoder.decode(raw))};}
export async function removeItem(id){const s=requireSession();return serialize(()=>access('items','readwrite',st=>st.delete(s.account.id+':'+id)));}
export async function usage(){const s=requireSession(),rows=await ownerRows(s.account.id);return{bytes:rows.reduce((n,r)=>n+r.size,0),songs:rows.filter(r=>r.kind==='song').length,recordings:rows.filter(r=>r.kind==='recording').length};}
export async function exportBackup(){const s=requireSession();await queue;const rows=await ownerRows(s.account.id);const encodeSeal=e=>({iv:b64(e.iv),ciphertext:b64(new Uint8Array(e.ciphertext))});const archive={format:'MixLab encrypted backup',version:1,account:{...s.account,salt:b64(s.account.salt),wrapped:encodeSeal(s.account.wrapped)},items:rows.map(r=>({...r,data:encodeSeal(r.data),info:encodeSeal(r.info)}))};return new Blob([JSON.stringify(archive)],{type:'application/json'});}
export async function restoreBackup(file,password){if(file.size>650*1024*1024)throw Error('La copia supera el tamaño permitido.');const backup=JSON.parse(await file.text());if(backup.format!=='MixLab encrypted backup'||backup.version!==1||!backup.account||!Array.isArray(backup.items))throw Error('No es una copia de MixLab compatible.');const decodeSeal=e=>({iv:unb64(e.iv),ciphertext:unb64(e.ciphertext).buffer}),a={...backup.account,salt:unb64(backup.account.salt),wrapped:decodeSeal(backup.account.wrapped)};if(a.iterations!==ITERATIONS||a.version!==1)throw Error('Copia incompatible.');const wrapping=await derive(password,a.salt);let raw;try{raw=await open(wrapping,a.wrapped,a.id);}catch{throw Error('La contraseña no abre esta copia.');}const key=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt']);new Uint8Array(raw).fill(0);const items=backup.items.map(r=>({...r,data:decodeSeal(r.data),info:decodeSeal(r.info)}));if(items.some(r=>r.owner!==a.id||r.key!==a.id+':'+r.id||!['song','recording','settings','draft','layer','stem','prepared','lyrics'].includes(r.kind)||!Number.isSafeInteger(r.size)||r.size<0)||new Set(items.map(r=>r.key)).size!==items.length||items.filter(r=>r.kind==='recording').length>MAX_RECORDINGS||items.filter(r=>r.kind==='song').length>MAX_SONGS||items.reduce((n,r)=>n+r.size,0)>MAX_PROFILE_BYTES)throw Error('La copia tiene datos o límites inválidos.');for(const r of items){const data=await open(key,r.data,r.key);if(data.byteLength!==r.size)throw Error('Copia incompleta.');JSON.parse(decoder.decode(await open(key,r.info,r.key+':meta')));}const existing=await access('profiles','readonly',s=>s.index('email').get(a.email));if(existing)throw Error('Ese perfil ya existe acá. Para evitar sobrescribir creaciones, restaurá en otro navegador o dispositivo.');const d=await database();await new Promise((resolve,reject)=>{const tx=d.transaction(['profiles','items'],'readwrite');tx.objectStore('profiles').add(a);for(const r of items)tx.objectStore('items').add(r);tx.oncomplete=()=>{d.close();resolve();};tx.onerror=tx.onabort=()=>{d.close();reject(tx.error);};});session={account:a,key};return activeProfile();}
